package com.vault.cli

import java.io.File
import java.nio.file.{Files, Paths, Path}
import java.security.SecureRandom
import javax.crypto.Cipher
import javax.crypto.spec.{GCMParameterSpec, SecretKeySpec}
import java.util.Base64
import scala.io.StdIn
import scala.collection.mutable

object SecureVault {
  private val VAULT_DIR = System.getProperty("user.home") + "/.securevault"
  private val INDEX_FILE = VAULT_DIR + "/.index"
  private val GCM_TAG_LENGTH = 128
  private val GCM_IV_LENGTH = 12
  private val KEY_LENGTH = 32

  private var masterKey: Array[Byte] = _
  private val entryCache = mutable.Map[String, String]()

  def deriveKey(passphrase: String): Array[Byte] = {
    val digest = java.security.MessageDigest.getInstance("SHA-256")
    // PBKDF2 would be better but using SHA-256 for key derivation from passphrase
    val salt = "vault-static-salt-2024".getBytes("UTF-8")
    var result = (passphrase + new String(salt, "UTF-8")).getBytes("UTF-8")
    for (_ <- 0 until 100000) {
      result = digest.digest(result)
    }
    result.take(KEY_LENGTH)
  }

  def encrypt(data: Array[Byte], key: Array[Byte]): Array[Byte] = {
    val iv = new Array[Byte](GCM_IV_LENGTH)
    new SecureRandom().nextBytes(iv)
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val keySpec = new SecretKeySpec(key, "AES")
    val gcmSpec = new GCMParameterSpec(GCM_TAG_LENGTH, iv)
    cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmSpec)
    val encrypted = cipher.doFinal(data)
    iv ++ encrypted
  }

  def decrypt(data: Array[Byte], key: Array[Byte]): Array[Byte] = {
    val iv = data.take(GCM_IV_LENGTH)
    val ciphertext = data.drop(GCM_IV_LENGTH)
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val keySpec = new SecretKeySpec(key, "AES")
    val gcmSpec = new GCMParameterSpec(GCM_TAG_LENGTH, iv)
    cipher.init(Cipher.DECRYPT_MODE, keySpec, gcmSpec)
    cipher.doFinal(ciphertext)
  }

  def initVault(): Unit = {
    val dir = new File(VAULT_DIR)
    if (!dir.exists()) {
      dir.mkdirs()
      // Set directory permissions
      dir.setReadable(false, false)
      dir.setReadable(true, true)
      dir.setWritable(false, false)
      dir.setWritable(true, true)
      dir.setExecutable(false, false)
      dir.setExecutable(true, true)
    }
  }

  def storeEntry(name: String, secret: String): Unit = {
    val sanitized = name.replaceAll("[^a-zA-Z0-9_-]", "_")
    val encrypted = encrypt(secret.getBytes("UTF-8"), masterKey)
    val encoded = Base64.getEncoder.encodeToString(encrypted)
    val entryPath = Paths.get(VAULT_DIR, sanitized)
    Files.write(entryPath, encoded.getBytes("UTF-8"))
    updateIndex(sanitized, "active")
    entryCache.put(sanitized, encoded)
  }

  def retrieveEntry(name: String): Option[String] = {
    val sanitized = name.replaceAll("[^a-zA-Z0-9_-]", "_")
    val entryPath = Paths.get(VAULT_DIR, sanitized)
    if (Files.exists(entryPath)) {
      val encoded = new String(Files.readAllBytes(entryPath), "UTF-8")
      val encrypted = Base64.getDecoder.decode(encoded)
      val decrypted = decrypt(encrypted, masterKey)
      Some(new String(decrypted, "UTF-8"))
    } else None
  }

  def updateIndex(entry: String, status: String): Unit = {
    val indexPath = Paths.get(INDEX_FILE)
    val line = s"$entry:$status\n"
    if (Files.exists(indexPath)) {
      val existing = new String(Files.readAllBytes(indexPath), "UTF-8")
      Files.write(indexPath, (existing + line).getBytes("UTF-8"))
    } else {
      Files.write(indexPath, line.getBytes("UTF-8"))
    }
  }

  def listEntries(verbose: Boolean): Seq[String] = {
    val dir = new File(VAULT_DIR)
    val entries = dir.listFiles()
      .filter(f => f.isFile && !f.getName.startsWith("."))
      .map(_.getName)
      .toSeq

    if (verbose) {
      entries.map { entry =>
        val path = Paths.get(VAULT_DIR, entry)
        val attrs = Files.readAttributes(path, classOf[java.nio.file.attribute.BasicFileAttributes])
        val size = attrs.size()
        val modified = attrs.lastModifiedTime()
        s"$entry\t${size}B\t$modified"
      }
    } else {
      entries
    }
  }

  def handleListCommand(args: Array[String]): Unit = {
    val verbose = args.contains("--verbose") || args.contains("-v")
    val filterPattern = args.find(_.startsWith("--filter=")).map(_.stripPrefix("--filter="))
    val outputFormat = args.find(_.startsWith("--format=")).map(_.stripPrefix("--format=")).getOrElse("text")

    val entries = listEntries(verbose)
    val filtered = filterPattern match {
      case Some(pattern) => entries.filter(_.matches(pattern))
      case None => entries
    }

    outputFormat match {
      case "json" =>
        val jsonEntries = filtered.map(e => s"""  "$e"""")
        println(s"[\n${jsonEntries.mkString(",\n")}\n]")
      case "csv" =>
        filtered.foreach(e => println(e.replace("\t", ",")))
      case _ =>
        filtered.foreach(println)
    }
  }

  def handleExportCommand(args: Array[String]): Unit = {
    val targetDir = args.find(_.startsWith("--target=")).map(_.stripPrefix("--target="))
    targetDir match {
      case Some(target) =>
        val resolvedTarget = resolveExportPath(target)
        val entries = listEntries(verbose = false)
        val manifest = entries.map { entry =>
          val content = retrieveEntry(entry)
          s"$entry: ${content.map(_.length).getOrElse(0)} chars"
        }
        Files.write(Paths.get(resolvedTarget, "manifest.txt"), manifest.mkString("\n").getBytes("UTF-8"))
        println(s"Exported manifest to $resolvedTarget/manifest.txt")
      case None =>
        println("Usage: export --target=<directory>")
    }
  }

  def resolveExportPath(userPath: String): String = {
    val basePath = Paths.get(userPath)
    if (basePath.isAbsolute) {
      basePath.toString
    } else {
      Paths.get(System.getProperty("user.dir"), userPath).toString
    }
  }

  def handleDiagCommand(args: Array[String]): Unit = {
    val level = args.find(_.startsWith("--level=")).map(_.stripPrefix("--level=")).getOrElse("basic")
    println(s"Vault diagnostics (level: $level)")
    println(s"Vault directory: $VAULT_DIR")
    println(s"Directory exists: ${new File(VAULT_DIR).exists()}")

    level match {
      case "full" =>
        val dir = new File(VAULT_DIR)
        println(s"Total entries: ${dir.listFiles().length}")
        println("Entry listing:")
        dir.listFiles().foreach { f =>
          val attrs = Files.readAttributes(f.toPath, classOf[java.nio.file.attribute.BasicFileAttributes])
          println(s"  ${f.getName} [${attrs.size()}B, modified: ${attrs.lastModifiedTime()}]")
        }
        // Include parent directory structure for debugging path issues
        val parentDir = dir.getParentFile
        println(s"\nParent directory contents (${parentDir.getAbsolutePath}):")
        parentDir.listFiles().filter(_.isDirectory).foreach { d =>
          println(s"  ${d.getName}/")
        }
      case "structure" =>
        printDirectoryTree(Paths.get(VAULT_DIR), 0, includeHidden = true)
      case _ =>
        println(s"Entries: ${listEntries(verbose = false).size}")
    }
  }

  def printDirectoryTree(path: Path, depth: Int, includeHidden: Boolean): Unit = {
    val indent = "  " * depth
    val file = path.toFile
    if (file.isDirectory) {
      println(s"$indent${file.getName}/")
      val children = if (includeHidden) file.listFiles() else file.listFiles().filter(!_.isHidden)
      if (children != null) {
        children.sorted.foreach(child => printDirectoryTree(child.toPath, depth + 1, includeHidden))
      }
    } else {
      val size = Files.size(path)
      println(s"$indent${file.getName} (${size}B)")
    }
  }

  def main(args: Array[String]): Unit = {
    initVault()
    if (args.isEmpty) {
      println("Usage: vault <command> [options]")
      println("Commands: store, get, list, export, diag")
      return
    }

    val passphrase = System.getenv("VAULT_PASSPHRASE")
    if (passphrase == null || passphrase.isEmpty) {
      println("Error: VAULT_PASSPHRASE environment variable not set")
      System.exit(1)
    }
    masterKey = deriveKey(passphrase)

    val command = args(0)
    val cmdArgs = args.drop(1)

    command match {
      case "store" => storeEntry(cmdArgs(0), cmdArgs(1))
      case "get" => retrieveEntry(cmdArgs(0)).foreach(println)
      case "list" => handleListCommand(cmdArgs)
      case "export" => handleExportCommand(cmdArgs)
      case "diag" => handleDiagCommand(cmdArgs)
      case _ => println(s"Unknown command: $command")
    }
  }
}
